changeSet.sql:
UPDATE harvest_logs h SET fish_type_id = (SELECT id FROM fish_types f WHERE f.name = h.fish_type AND f.tenant_id = h.tenant_id);
UPDATE sample_logs s SET fish_type_id = (SELECT id FROM fish_types f WHERE f.name = s.fish_type AND f.tenant_id = s.tenant_id);
UPDATE fish_seeds f SET fish_type_id = (SELECT id FROM fish_types ft WHERE ft.name = f.type AND ft.tenant_id = f.tenant_id);
UPDATE fish_stock_events f SET fish_type_id = (SELECT id FROM fish_types ft WHERE ft.name = f.fish_type AND ft.tenant_id = f.tenant_id);
